import * as React from "react";
import { cn } from "@/lib/utils";

/** "Smart Indigo" gradient. */
export const GradientSmartIndigo_CSS = "linear-gradient(0deg, #b224ef 0%, #7579ff 100%)";

export function GradientSmartIndigo({ className, style, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      className={cn("h-40 w-full rounded-xl", className)}
      style={{ backgroundImage: "linear-gradient(0deg, #b224ef 0%, #7579ff 100%)", ...style }}
      {...props}
    />
  );
}
